// The professors. All five are invented. Each holds a mistaken position and gives it up one objection at a time.
// A round is a claim and three replies: one that answers it, and two that sound like answers and are not.
// rounds(C, e): C is the case data. e is the player's own experiment, used by the last professor only.
const pc = (v, d = 0) => (v * 100).toFixed(d) + '%';
const n = (v) => Math.round(v).toLocaleString('en');
const per100 = (v) => (v * 100 < 1 ? (v * 100).toFixed(2) : String(Math.round(v * 100)));
const signed = (v) => (v >= 0 ? 'up ' : 'down ') + Math.abs(v * 100).toFixed(0) + '%';

